edits.replacement:
#root #title .kbrow b{ font-size:var(--fs-fine) !important; }
/* v28.xx (cw-title-clean), the critic (2 of 5, P0/P1) on the title: "six stacked rows of small text between the logo and the menu; delete the subtitle, move Go fullscreen and Settings top-right, move the key legend to a bottom strip, the logo about 96px, version in a 14px footer". Logo 64 to 96px; Go fullscreen and Settings 44px high at the top-right, 32px from the top and 5vw from the edge; the version bottom-left, 16px, tx-2; the key legend one bottom strip, 16px, 24px from the bottom; the saves note line gone. */
#root #title .wordmark{ font-size:96px; }
#root #title #titleres{ position:fixed; top:32px; right:5vw; margin:0 !important; display:flex; gap:12px; z-index:2; }
#root #title #titleres button{ min-height:44px; padding:0 24px; font-size:16px; }
#root #title #titlefoot{ position:fixed; left:5vw; bottom:24px; margin:0; font:600 var(--fs-fine)/1 var(--f-cond); letter-spacing:var(--track); color:var(--tx-2); }
#root #title .kbrow, #root #title .padrow{ position:fixed; left:0; right:0; bottom:24px; margin:0 !important; text-align:center; font-size:16px !important; }
#root #title #slotnote{ margin:0 !important; }

check:
{v:'VER',what:'the title is cleaned: 96px logo, no best-in-fullscreen sentence, no first-time sentence, version in a footer, key legend a fixed bottom strip, Go fullscreen top-right',
 run:function(){
   var t=document.getElementById('title'), wm=t&&t.querySelector('.wordmark'), tr=document.getElementById('titleres'), kb=t&&t.querySelector('.kbrow'), ft=document.getElementById('titlefoot'), was, bad=[];
   if(!t||!wm||!tr||!kb) return 'SKIP: no title here';
   was=t.classList.contains('on'); if(!was) t.classList.add('on');
   var keep={runs:P.runs,welcomed:P.welcomed};
   try{
     if(parseFloat(getComputedStyle(wm).fontSize)<90) bad.push('the logo is '+getComputedStyle(wm).fontSize+', not 96px');
     if(/best in fullscreen/i.test(tr.textContent||'')) bad.push('the best-in-fullscreen sentence is still on the title');
     if(getComputedStyle(tr).position!=='fixed') bad.push('Go fullscreen and Settings are not a fixed top-right row');
     if(getComputedStyle(kb).position!=='fixed') bad.push('the key legend is not a fixed bottom strip');
     if(!ft||!ft.querySelector('#titlever')) bad.push('the version is not in the footer');
     if(ft&&/extraction raid/i.test(ft.textContent||'')) bad.push('the subtitle is still on the title');
     if(typeof titleRefresh==='function'){
       P.runs=0; try{ titleRefresh(); }catch(_t){}
       var sub=document.getElementById('titlesub');
       if(sub&&(sub.textContent||'').trim()) bad.push('the first-time sentence is still on the title: '+sub.textContent);
     }
   } finally { P.runs=keep.runs; P.welcomed=keep.welcomed; try{ titleRefresh(); }catch(_r){} if(!was) t.classList.remove('on'); }
   return bad.length?bad.join('; '):null; }},
